  "contradictory_card_ids": ["C55","C57","C66","C70","C71","C72","C74"],
  "prediction_basis_card_ids": ["C01","C02","C04","C10","C13","C14","C19","C27","C43","C64"],
  "claims": [
    {
      "claim": "Human absolute oral bioavailability values for structurally related lipophilic basic amines/amides are all above the 20% threshold: diphenhydramine 42–72%, dapoxetine 42%, trimipramine 41.4%, milnacipran 85%.",
      "card_ids": ["C01","C02","C04","C10","C13","C14","C19","C27"]
    },
    {
      "claim": "Permeability records for lipophilic basic/amide drugs show high absorptive permeability and no net efflux in several assays (loperamide Papp 17.0×10^-6 cm/s, ER 0.8; praziquantel Papp 39×10^-6 cm/s, ER 1; (+)CLA ER 0.867; TH Papp 45.38×10^-6 cm/s), supporting adequate absorption.",
      "card_ids": ["C43","C59","C61","C63","C64"]
    },
    {
      "claim": "Loperamide, a structurally similar diphenylamide, is a P-gp substrate (verapamil increases A→B transport) and has moderate-to-high hepatic intrinsic clearance in human liver microsomes (44–48 µL/min/mg) and human hepatocytes (13 µL/min/mg), indicating potential presystemic loss; however, these are in vitro mechanistic results without a direct F measurement for the query.",
      "card_ids": ["C55","C57","C66","C70","C71","C72","C74"]
    },
    {
      "claim": "No direct absolute oral bioavailability measurement exists for the query; the only low-F records are species-specific animal values (diphenhydramine in dogs, ampicillin in fasted calves) and are not transferable affirmative evidence for F<20%.",
      "card_ids": ["C23","C24"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C66","C68","C70","C71","C72","C74"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "No human F data for loperamide or a closer structural analog; loperamide is similar but only in vitro efflux and clearance data are available.",
    "No query-specific solubility/dissolution data; L4 fexofenadine solubility values are formulation-specific and not directly transferable.",
    "No query-specific P-gp/efflux or hepatic clearance measurement; loperamide data are analog-based with moderate transferability.",
    "The query's low neutral fraction and high logP leave uncertainty about solubility and dissolution, but this is not affirmative evidence for F<20%.",
    "L6 hepatic clearance values are in vitro intrinsic clearances, not in vivo F or hepatic extraction; units and assay systems vary."
  ],
  "decision_summary": "L6 adds moderate-to-high hepatic intrinsic clearance for loperamide, a structurally similar diphenylamide, which together with L5 P-gp efflux evidence raises a mechanistic concern for presystemic loss. However, this is analog-based in vitro evidence without a direct F measurement, and the strongest transferable direct evidence remains human F values >20% for related basic amines/amides. Prediction remains high with low confidence; evidence basis weakened."
}

